impl AntiSandwich<Plane> for Flector {
    type Output = Plane;
    // Operative Statistics for this implementation:
    //           add/sub      mul      div
    //      f32       12       25        0
    //    simd4        6        6        0
    // Totals...
    // yes simd       18       31        0
    //  no simd       36       49        0
    fn anti_sandwich(self, other: Plane) -> Self::Output {
        use crate::elements::*;
        let geometric_anti_product_g0 = Simd32x4::from([
            -(self[e45] * other[e4235]) - (self[e4315] * other[e4125]),
            -(self[e45] * other[e4315]) - (self[e4125] * other[e4235]),
            -(self[e45] * other[e4125]) - (self[e4235] * other[e4315]),
            (self[e4315] * other[e4315]) + (self[e4125] * other[e4125]),
        ]) + (self.group1().zxyx() * other.group0().yzxx());
        let geometric_anti_product_g1 = Simd32x4::from([
            -(self[e25] * other[e4125]) - (self[e3215] * other[e4235]),
            -(self[e35] * other[e4235]) - (self[e3215] * other[e4315]),
            -(self[e15] * other[e4315]) - (self[e3215] * other[e4125]),
            (self[e35] * other[e4125]) + (self[e45] * other[e3215]),
        ]) + (self.group0().zxyx() * other.group0().yzxx())
            + (other.group0().wwwy() * self.group1().xyz().with_w(self[e25]));
        Plane::from_groups(
            // e4235, e4315, e4125, e3215
            Simd32x4::from([
                geometric_anti_product_g0[3] * self[e4235],
                geometric_anti_product_g0[3] * self[e4315],
                geometric_anti_product_g0[3] * self[e4125],
                -(geometric_anti_product_g0[1] * self[e25])
                    - (geometric_anti_product_g0[2] * self[e35])
                    - (geometric_anti_product_g1[0] * self[e4235])
                    - (geometric_anti_product_g1[1] * self[e4315])
                    - (geometric_anti_product_g1[2] * self[e4125]),
            ]) + (geometric_anti_product_g0.xyxw() * self.group0().ww().with_zw(self[e4315], self[e3215]))
                + (self.group1().zx().with_zw(self[e45], geometric_anti_product_g1[3] * self[e45]) * geometric_anti_product_g0.yzz().with_w(1.0))
                - (geometric_anti_product_g0.zxyx() * self.group1().yzx().with_w(self[e15])),
        )
    }
}
