        let geometric_anti_product_g1_xyz = (Simd32x3::from(other[e45]) * self.group5())
            + (Simd32x3::from([self[e42], self[e1234], self[e1234]]) * other.group0().zyz())
            + (Simd32x3::from([self[e1234], self[e43], self[e41]]) * other.group0().xxy())
            - (self.group4().zxy() * other.group0().yzx());
        let geometric_anti_product_g1_w = other[e45] * self[e1234];
        let geometric_anti_product_g2 = (other[e15] * self[e23]) + (other[e25] * self[e31]) + (other[e35] * self[e12])
            - (other[e15] * self[e4235])
            - (other[e25] * self[e4315])
            - (other[e35] * self[e4125])
            - (other[e45] * self[e3215]);
        let geometric_anti_product_g3 = Simd32x4::from([
            (other[e15] * self[e321]) + (other[e35] * self[e2]) + (other[e35] * self[e425]) + (other[e45] * self[e235]),
            (other[e15] * self[e435]) + (other[e25] * self[e12345]) + (other[e25] * self[e321]) + (other[e45] * self[e315]),
            (other[e25] * self[e415]) + (other[e35] * self[e12345]) + (other[e35] * self[e321]) + (other[e45] * self[e125]),
            other[e35] * self[e412] * -1.0,
        ]) + (Simd32x4::from([self[e12345], self[e3], self[e1], self[e12345]]) * other.group0().xxyw())
            - (other.group0().yzxx() * self.group1().zxy().with_w(self[e423]))
            - (other.group0().yzxy() * self.group6().zxy().with_w(self[e431]));
